{"implementation":"import math
def solve(case):
    matrix = case["matrix"]
    if not matrix:
        N = 0
        M = 0
    else:
        N = len(matrix)
        M = len(matrix[0]) if N > 0 else 0
    df = [0] * M
    for row in matrix:
        for j, val in enumerate(row):
            if val == 1:
                df[j] += 1
    if N == 0:
        idf = [0.0] * M
    else:
        idf = [math.log(N / (1 + d)) for d in df]
    weighted_matrix = [[0.0] * M for _ in range(N)]
    for i, row in enumerate(matrix):
        for j, val in enumerate(row):
            if val == 1:
                weighted_matrix[i][j] = idf[j]
    row_degree = [sum(row) for row in weighted_matrix]
    return {
        "idf": idf,
        "row_degree": row_degree,
        "weighted_matrix": weighted_matrix
    }"}
